CREATE OR REPLACE FUNCTION public.default_client_account_manager() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT NEW.is_test AND NOT NEW.is_demo AND NEW.account_manager_id IS NULL THEN SELECT id INTO NEW.account_manager_id FROM public.profiles WHERE email='shalini@alcorgetaways.com' AND status='active'; IF NEW.account_manager_id IS NULL THEN RAISE EXCEPTION 'Default Account Manager is unavailable; ask management to assign one'; END IF; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.default_client_account_manager() FROM PUBLIC,anon,authenticated; CREATE TRIGGER default_client_account_manager BEFORE INSERT ON public.clients FOR EACH ROW EXECUTE FUNCTION public.default_client_account_manager();